import aesgcm_fast


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        aad = problem["associated_data"]
        if aad:
            ciphertext, tag = aesgcm_fast.encrypt(key, nonce, plaintext, aad)
        else:
            ciphertext, tag = aesgcm_fast.encrypt(key, nonce, plaintext)
        return {"ciphertext": ciphertext, "tag": tag}

