#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

#define N (60*1024*1024)
#define THREADS 4

static unsigned char *pt, *out, key[16];

static void enc_range(int tid, size_t start, size_t len, unsigned char iv[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen = 0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, out + start, &outlen, pt + start, (int)len);
    EVP_EncryptFinal_ex(ctx, out + start + outlen, &outlen);
    EVP_CIPHER_CTX_free(ctx);
}

typedef struct { int tid; size_t start; size_t len; unsigned char iv[16]; } job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    enc_range(j->tid, j->start, j->len, j->iv);
    return NULL;
}

static double now(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main(void) {
    pt = malloc(N);
    out = malloc(N);
    memset(pt, 0x5a, N);
    RAND_bytes_dummy: ;
    for (int i = 0; i < 16; i++) key[i] = i + 1;

    /* single thread CTR */
    unsigned char iv[16] = {0};
    double t0 = now();
    enc_range(0, 0, N, iv);
    double t1 = now();
    printf("CTR 1 thread: %.4f s  %.0f MB/s\n", t1-t0, 60.0/(t1-t0));

    /* single thread GCM */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char nonce[12] = {0};
    unsigned char tag[16];
    int outlen = 0;
    unsigned char aad[32] = {0};
    t0 = now();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, out, &outlen, pt, N);
    EVP_EncryptFinal_ex(ctx, out, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    t1 = now();
    printf("GCM 1 thread: %.4f s  %.0f MB/s\n", t1-t0, 60.0/(t1-t0));
    EVP_CIPHER_CTX_free(ctx);

    /* parallel CTR */
    for (int th = 2; th <= 8; th *= 2) {
        size_t chunk = (N / th) & ~15UL;
        pthread_t threads[16];
        job_t jobs[16];
        t0 = now();
        for (int i = 0; i < th; i++) {
            jobs[i].tid = i;
            jobs[i].start = i * chunk;
            jobs[i].len = (i == th-1) ? (N - jobs[i].start) : chunk;
            memset(jobs[i].iv, 0, 16);
            jobs[i].iv[0] = (unsigned char)i;
            pthread_create(&threads[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < th; i++) pthread_join(threads[i], NULL);
        t1 = now();
        printf("CTR %d threads: %.4f s  %.0f MB/s\n", th, t1-t0, 60.0/(t1-t0));
    }
    return 0;
}
