#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <openssl/evp.h>

/* GF(2^128) multiplication, reflected (GCM) representation.
   H and X are 16-byte big-endian blocks. */

static void gcm_mul(uint8_t x[16], const uint8_t h[16]) {
    uint8_t z[16] = {0};
    uint8_t v[16];
    memcpy(v, h, 16);
    for (int i = 0; i < 128; i++) {
        if (x[i >> 3] & (1u << (7 - (i & 7)))) {
            for (int j = 0; j < 16; j++) z[j] ^= v[j];
        }
        /* v = v >> 1, if LSB was 1 xor R = 0xe1 || 0^120 */
        int lsb = v[15] & 1;
        for (int j = 15; j > 0; j--) v[j] = (v[j] >> 1) | (v[j-1] << 7);
        v[0] >>= 1;
        if (lsb) v[0] ^= 0xe1;
    }
    memcpy(x, z, 16);
}

/* 4-bit table GHASH */
typedef struct { uint8_t t[16][16]; } ghash_tab;

static void ghash_init(ghash_tab *tab, const uint8_t h[16]) {
    memset(tab->t[0], 0, 16);
    memcpy(tab->t[1], h, 16); /* wait, table should be powers of H: H<<0 ... better build by doubling */
    /* rebuild properly: t[0]=0, t[8]? Let's do iterative doubling from H as t[8] or just successive add.
       Standard 4-bit: table[i] = i * H. */
    memset(tab->t, 0, sizeof(tab->t));
    memcpy(tab->t[8], h, 16); /* 1000b * H = H, then double down? 
       Actually easiest: compute H, 2H, 4H, 8H by doubling, then fill by xor. */
    uint8_t p[16];
    memcpy(p, h, 16); /* 1*H */
    memcpy(tab->t[1], p, 16);
    /* double to get 2H, 4H, 8H */
    uint8_t d[5][16];
    memcpy(d[0], h, 16); /* 1H */
    for (int k = 1; k <= 3; k++) {
        /* left shift (multiply by x in GCM is right shift of the byte array!) 
           In GCM, multiplying by x (the polynomial variable) is a right shift
           because the representation is reflected. 
           i*H for i in 0..15:
           We'll just use gcm_mul for the 15 entries — init is once. */
    }
    uint8_t x[16];
    for (int i = 2; i < 16; i++) {
        memset(x, 0, 16);
        x[15] = (uint8_t)i; /* no that's wrong, gcm_mul multiplies two field elements */
    }
    /* Compute i*H by adding H, i times, using field add (xor) after multiplying? 
       Just call gcm_mul(i_as_element, H) where i_as_element is the field element i.
       In GCM bit ordering the integer i corresponds to the top bits... this is getting messy.
       For a throughput bench of the inner loop, precompute table via repeated gcm_mul of basis.
    */
    uint8_t basis[16];
    memcpy(basis, h, 16); /* this is 1*H where 1 is the multiplicative identity? 
       NO: H itself is the hash subkey. table[i] = i * H, with i in 0..15, where i is the 4-bit
       nibble in the same bit ordering as the data bytes (MSB first within nibble). */
    memset(tab->t[0], 0, 16);
    for (int i = 1; i < 16; i++) {
        /* i * H = xor of basis powers. Compute by gcm_mul of element with value i in top nibble? 
           Simpler and correct: start from 0 and for each i, we can obtain i*H from (i-1)*H + H,
           but addition in the integer sense is not xor. 
           Use: represent integer nibble as a field element occupying the most significant 4 bits
           (since data is processed MSB first). Element for nibble value v is byte0 = v<<4.
           Then table[v] = that_element * H. */
        uint8_t e[16] = {0};
        e[0] = (uint8_t)(i << 4);
        gcm_mul(e, h);
        memcpy(tab->t[i], e, 16);
    }
}

static void ghash_update_4bit(ghash_tab *tab, uint8_t y[16], const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i += 16) {
        for (int j = 0; j < 16; j++) y[j] ^= data[i+j];
        uint8_t tmp[16] = {0};
        for (int j = 0; j < 16; j++) {
            uint8_t b = y[j];
            uint8_t hi = b >> 4;
            uint8_t lo = b & 0xf;
            /* multiply current tmp by x^8 (shift 8 bits = 1 byte right in GCM reflected? )
               Standard 4-bit GHASH processes one nibble at a time with a right shift of the accumulator.
               This is the classic algorithm from Gueron / McGrew-Viega.
            */
            (void)hi; (void)lo;
        }
        /* Use byte-wise: for each of 16 bytes, two nibbles. We'll implement the shift-xor form. */
        uint8_t z[16];
        memset(z, 0, 16);
        for (int k = 0; k < 16; k++) {
            uint8_t b = y[k];
            /* process high nibble: z = (z >> 4) xor table[high]  -- but shift is across whole z, expensive.
               Do it nibble by nibble properly. */
            (void)b;
        }
        /* Fallback correct but slower path for correctness later. For speed estimate, do 32 nibble muls via table xor with shifts. */
        /* Implement classic:
           for each nibble from MSB:
             rem = z[15] & 0x0f  ... actually let's look up a known implementation.
        */
        /* Simple correct approach for bench of memory bandwidth + xor only: just xor all blocks (lower bound of GHASH data touch). */
        (void)tmp;
    }
}

/* Correct 4-bit GHASH from commonly used implementation (BearSSL / NIST style, reflected). */
static void ghash_4bit(const uint8_t table[16][16], uint8_t y[16], const uint8_t *data, size_t nblocks) {
    for (size_t b = 0; b < nblocks; b++) {
        const uint8_t *p = data + b*16;
        uint8_t x[16];
        for (int i = 0; i < 16; i++) x[i] = y[i] ^ p[i];

        uint8_t z[16];
        /* start with high nibble of x[0] */
        memcpy(z, table[x[0] >> 4], 16);
        /* then for each subsequent nibble, shift z right by 4 and xor table */
        for (int i = 0; i < 16; i++) {
            uint8_t lo = x[i] & 0x0f;
            uint8_t hi_next = (i + 1 < 16) ? (x[i+1] >> 4) : 0;
            /* shift z right 4 bits */
            uint8_t rem = z[15] & 0x0f;
            for (int j = 15; j > 0; j--) z[j] = (z[j] >> 4) | (z[j-1] << 4);
            z[0] >>= 4;
