               rem * 0xe1 shifted into the top. The 16 possible 4-bit reductions:
               This naive shift without reduction is WRONG. Skip. */
            (void)lo; (void)hi_next; (void)rem;
        }
        (void)z;
    }
}

/* Throughput of PCLMUL-quality estimate: time a simple xor-chain over 60MB (memory bandwidth)
   and a software 1-bit ghash over a small buffer to estimate, then also try compiler auto-vectorization
   of a schoolbook multiply unrolled. */

static double now(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* Unrolled 128-bit carryless-ish using 64-bit with reduction. 
   Represent block as two uint64 little-endian for speed experiment. */
static inline void mul_gf_64style(uint8_t x[16], const uint8_t h[16]) {
    /* bit by bit but on uint64 — still slow, just for structure */
    uint64_t x0, x1, h0, h1, z0=0, z1=0, v0, v1;
    memcpy(&x0, x, 8); memcpy(&x1, x+8, 8);
    memcpy(&h0, h, 8); memcpy(&h1, h+8, 8);
    /* This bit order is wrong for GCM but fine for throughput measurement of the inner op count. */
    v0 = h0; v1 = h1;
    for (int i = 0; i < 64; i++) {
        uint64_t m = -((x0 >> i) & 1);
        z0 ^= v0 & m; z1 ^= v1 & m;
        uint64_t lsb = v1 & 1;
        v1 = (v1 >> 1) | (v0 << 63);
        v0 >>= 1;
        if (lsb) v0 ^= 0xe100000000000000ULL;
    }
    for (int i = 0; i < 64; i++) {
        uint64_t m = -((x1 >> i) & 1);
        z0 ^= v0 & m; z1 ^= v1 & m;
        uint64_t lsb = v1 & 1;
        v1 = (v1 >> 1) | (v0 << 63);
        v0 >>= 1;
        if (lsb) v0 ^= 0xe100000000000000ULL;
    }
    memcpy(x, &z0, 8); memcpy(x+8, &z1, 8);
}

int main(void) {
    size_t N = 4*1024*1024; /* 4MB for slow algos */
    uint8_t *data = malloc(N);
    memset(data, 0x5a, N);
    uint8_t h[16], y[16] = {0};
    for (int i = 0; i < 16; i++) h[i] = i*17+3;

    double t0 = now();
    size_t blocks = N/16;
    for (size_t i = 0; i < blocks; i++) {
        for (int j = 0; j < 16; j++) y[j] ^= data[i*16+j];
        gcm_mul(y, h);
    }
    double t1 = now();
    double mb = N/1e6;
    printf("1-bit GHASH on %.1fMB: %.4fs  %.1f MB/s\n", mb, t1-t0, mb/(t1-t0));

    /* xor-only bandwidth */
    uint8_t acc[16] = {0};
    size_t N2 = 60*1024*1024;
    uint8_t *d2 = malloc(N2);
    memset(d2, 1, N2);
    t0 = now();
    for (size_t i = 0; i < N2; i += 16) {
        for (int j = 0; j < 16; j++) acc[j] ^= d2[i+j];
    }
    t1 = now();
    printf("xor-only 60MB: %.4fs  %.0f MB/s  acc0=%u\n", t1-t0, 60.0/(t1-t0), acc[0]);

    /* 64-style mul throughput on 1MB */
    memset(y, 0, 16);
    size_t N3 = 1*1024*1024;
    t0 = now();
    for (size_t i = 0; i < N3/16; i++) {
        for (int j = 0; j < 16; j++) y[j] ^= data[i*16+j];
        mul_gf_64style(y, h);
    }
    t1 = now();
    printf("64style mul on 1MB: %.4fs  %.1f MB/s\n", t1-t0, 1.0/(t1-t0));
    return 0;
}
