extern void gcm_init_clmul(void *Htable, const void *H);
extern void gcm_ghash_clmul(void *Xi, const void *Htable, const unsigned char *in, size_t len);

static void bswap8_inplace_copy(unsigned char dst[16], const unsigned char src[16]) {
    for (int i = 0; i < 8; i++) {
        dst[i] = src[7 - i];
        dst[8 + i] = src[15 - i];
    }
}

static void inc32_copy(unsigned char dst[16], const unsigned char src[16], uint32_t add) {
    memcpy(dst, src, 12);
    uint32_t c = ((uint32_t)src[12] << 24) | ((uint32_t)src[13] << 16) |
                 ((uint32_t)src[14] << 8) | (uint32_t)src[15];
    c += add;
    dst[12] = (unsigned char)(c >> 24);
    dst[13] = (unsigned char)(c >> 16);
    dst[14] = (unsigned char)(c >> 8);
    dst[15] = (unsigned char)c;
}

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t blocks;
    const void *key;
    unsigned char ivec[16];
} ctr_job_t;

static void *ctr_worker(void *arg) {
    ctr_job_t *j = (ctr_job_t *)arg;
    aesni_ctr32_encrypt_blocks(j->in, j->out, j->blocks, j->key, j->ivec);
    return NULL;
}

typedef struct {
    unsigned char *Xi;
    const void *Htable;
    const unsigned char *in;
    size_t len;
} ghash_job_t;

static void *ghash_worker(void *arg) {
    ghash_job_t *j = (ghash_job_t *)arg;
    gcm_ghash_clmul(j->Xi, j->Htable, j->in, j->len);
    return NULL;
