/* Build padded GHASH input: AAD || CT || lengths. CT is written in-place into a
   caller-provided buffer that already holds ciphertext (possibly with tail bytes
   we must not require to be padded in the original). We allocate one buffer. */
static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, plaintext, aad;
    int have_aad = 1;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &plaintext, &aad)) {
        PyErr_Clear();
        have_aad = 0;
        if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &plaintext))
            return NULL;
    }

    if (key.len != 16 && key.len != 24 && key.len != 32) {
        PyErr_SetString(PyExc_ValueError, "Invalid key size");
        goto err_release;
    }
    if (nonce.len != 12) {
        /* Fall back not implemented for non-96-bit nonce in fast path.
           Handle via EVP below. */
    }

    /* Non-12-byte nonce: use EVP for correctness. */
    if (nonce.len != 12) {
        const EVP_CIPHER *cipher = NULL;
        if (key.len == 16) cipher = EVP_aes_128_gcm();
        else if (key.len == 24) cipher = EVP_aes_192_gcm();
        else cipher = EVP_aes_256_gcm();

        PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, plaintext.len);
        PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
        if (!ct_obj || !tag_obj) { Py_XDECREF(ct_obj); Py_XDECREF(tag_obj); goto err_release; }
        unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
        unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        int ok = 0, outlen = 0, written = 0;
        if (!ctx) goto evp_done;
        if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) goto evp_done;
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL) != 1) goto evp_done;
        if (EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) goto evp_done;
        if (have_aad && aad.len > 0) {
            if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) goto evp_done;
        }
        if (plaintext.len > 0) {
            if (EVP_EncryptUpdate(ctx, ct, &outlen, plaintext.buf, (int)plaintext.len) != 1) goto evp_done;
            written = outlen;
        }
        if (EVP_EncryptFinal_ex(ctx, ct + written, &outlen) != 1) goto evp_done;
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) goto evp_done;
        ok = 1;
    evp_done:
        if (ctx) EVP_CIPHER_CTX_free(ctx);
        PyBuffer_Release(&key);
        PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext);
        if (have_aad) PyBuffer_Release(&aad);
        if (!ok) {
            Py_DECREF(ct_obj); Py_DECREF(tag_obj);
            PyErr_SetString(PyExc_RuntimeError, "AES-GCM encryption failed");
            return NULL;
        }
