    }

    /* Fast path: 12-byte nonce, AES-NI CTR + CLMUL GHASH, overlapped. */
    unsigned char aes_key[256] __attribute__((aligned(16)));
    memset(aes_key, 0, sizeof(aes_key));
    if (aesni_set_encrypt_key((unsigned char *)key.buf, (int)key.len * 8, aes_key) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "key setup failed");
        goto err_release;
