    unsigned char Htable[1024] __attribute__((aligned(64)));
    memset(Htable, 0, sizeof(Htable));
    gcm_init_clmul(Htable, H_le);

    unsigned char j0[16];
    memcpy(j0, nonce.buf, 12);
    j0[12] = 0; j0[13] = 0; j0[14] = 0; j0[15] = 1;

    unsigned char ekj0[16];
    aesni_encrypt(j0, ekj0, aes_key);

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, plaintext.len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) {
        Py_XDECREF(ct_obj); Py_XDECREF(tag_obj);
        goto err_release;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);

