       We hash AAD first (small), then overlap CT encryption with... CT must exist
       before hashing it. So: encrypt full blocks in parallel across 2 threads
       while we cannot hash CT yet. Then hash. 
       Better overlap: split CT into two halves. Thread A encrypts half 1, thread B
       encrypts half 2. Main thread cannot hash until both done. That's just parallel CTR.
       To overlap GHASH with CTR: encrypt half 1, then start GHASH of half 1 concurrently
       with CTR of half 2. */
    unsigned char ctr_iv[16];
    inc32_copy(ctr_iv, j0, 1);

    size_t aad_len = (have_aad && aad.buf) ? (size_t)aad.len : 0;

    /* Prepare AAD hash contribution first (tiny). */
    unsigned char Xi[16];
    memset(Xi, 0, 16);
    if (aad_len) {
        size_t aad_full = aad_len & ~((size_t)15);
        size_t aad_rem = aad_len & 15;
