        aesni_ctr32_encrypt_blocks(pt, ct, mid, aes_key, ctr_iv);

        /* second half IV */
        unsigned char ctr_iv2[16];
        inc32_copy(ctr_iv2, ctr_iv, (uint32_t)mid);

        pthread_t th_ctr, th_gh;
        ctr_job_t cj;
        cj.in = pt + mid * 16;
        cj.out = ct + mid * 16;
        cj.blocks = nblocks - mid;
        cj.key = aes_key;
        memcpy(cj.ivec, ctr_iv2, 16);

        ghash_job_t gj;
        gj.Xi = Xi;
        gj.Htable = Htable;
        gj.in = ct;
        gj.len = mid * 16;

        pthread_create(&th_ctr, NULL, ctr_worker, &cj);
        pthread_create(&th_gh, NULL, ghash_worker, &gj);
        pthread_join(th_ctr, NULL);
        pthread_join(th_gh, NULL);

        /* hash second half */
        gcm_ghash_clmul(Xi, Htable, ct + mid * 16, (nblocks - mid) * 16);
    } else if (nblocks == 1) {
        aesni_ctr32_encrypt_blocks(pt, ct, 1, aes_key, ctr_iv);
        gcm_ghash_clmul(Xi, Htable, ct, 16);
    }

    if (rem) {
        unsigned char next_ctr[16];
        inc32_copy(next_ctr, ctr_iv, (uint32_t)nblocks);
        unsigned char stream[16];
        aesni_encrypt(next_ctr, stream, aes_key);
        size_t base = nblocks * 16;
        for (size_t i = 0; i < rem; i++)
            ct[base + i] = pt[base + i] ^ stream[i];
        unsigned char last[16];
        memset(last, 0, 16);
        memcpy(last, ct + base, rem);
        gcm_ghash_clmul(Xi, Htable, last, 16);
    }

    /* lengths block */
    unsigned char lengths[16];
    uint64_t alen_bits = (uint64_t)aad_len * 8;
    uint64_t clen_bits = (uint64_t)pt_len * 8;
    for (int i = 7; i >= 0; i--) {
        lengths[i] = (unsigned char)(alen_bits & 0xff);
        alen_bits >>= 8;
        lengths[8 + i] = (unsigned char)(clen_bits & 0xff);
        clen_bits >>= 8;
    }
    gcm_ghash_clmul(Xi, Htable, lengths, 16);

    for (int i = 0; i < 16; i++)
