    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext);
    if (have_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct_obj, tag_obj);

err_release:
    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext);
    if (have_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", aesgcm_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_aesgcm_fast(void) {
    return PyModule_Create(&moduledef);
}
