static worker_t workers[MAXTH];

static void *wfn(void *arg) {
    worker_t *w = arg;
    while (!atomic_load(&w->stop)) {
        if (atomic_load(&w->go)) {
            aesni_ctr32_encrypt_blocks(w->in, w->out, w->blocks, aes_key, w->ivec);
            atomic_store(&w->done, 1);
            atomic_store(&w->go, 0);
        }
    }
    return NULL;
}

static void launch(int nthreads) {
    for (int i = 0; i < nthreads; i++) {
        atomic_store(&workers[i].done, 0);
        atomic_store(&workers[i].go, 1);
    }
    for (int i = 0; i < nthreads; i++) {
        while (!atomic_load(&workers[i].done)) ;
    }
}

int main(void) {
    pt = aligned_alloc(64, N);
    ct = aligned_alloc(64, N);
    memset(pt, 0x5a, N);
    unsigned char key[16];
    for (int i = 0; i < 16; i++) key[i] = i+1;
    aesni_set_encrypt_key(key, 128, aes_key);

    pthread_t th[MAXTH];
    for (int i = 0; i < MAXTH; i++) {
        atomic_store(&workers[i].go, 0);
        atomic_store(&workers[i].done, 0);
        atomic_store(&workers[i].stop, 0);
        workers[i].id = i;
        pthread_create(&th[i], NULL, wfn, &workers[i]);
    }

    size_t blocks = N/16;
    for (int nt = 1; nt <= 8; nt *= 2) {
        size_t chunk = blocks / nt;
        /* warmup */
        for (int i = 0; i < nt; i++) {
            workers[i].in = pt + i*chunk*16;
            workers[i].out = ct + i*chunk*16;
            workers[i].blocks = (i==nt-1) ? (blocks - i*chunk) : chunk;
            memset(workers[i].ivec, 0, 16);
            workers[i].ivec[15] = (unsigned char)(i+1);
        }
        launch(nt);
        double t0 = now();
        int iters = 4;
        for (int k = 0; k < iters; k++) launch(nt);
        double t1 = now();
        printf("CTR %d persistent threads: %.4f s  %.0f MB/s\n", nt, (t1-t0)/iters, 60.0/((t1-t0)/iters));
    }

    /* single thread baseline tight */
    unsigned char iv[16] = {0};
    double t0 = now();
    for (int k = 0; k < 4; k++)
        aesni_ctr32_encrypt_blocks(pt, ct, blocks, aes_key, iv);
    double t1 = now();
    printf("CTR 1 direct: %.4f s  %.0f MB/s\n", (t1-t0)/4, 60.0/((t1-t0)/4));

    /* ghash */
    unsigned char H[16], Hle[16], Ht[1024], Xi[16];
    unsigned char zero[16] = {0};
    aesni_encrypt(zero, H, aes_key);
    for (int i = 0; i < 8; i++) { Hle[i]=H[7-i]; Hle[8+i]=H[15-i]; }
    gcm_init_clmul(Ht, Hle);
    memset(Xi, 0, 16);
    t0 = now();
    for (int k = 0; k < 4; k++) {
        memset(Xi, 0, 16);
        gcm_ghash_clmul(Xi, Ht, ct, N);
    }
    t1 = now();
    printf("GHASH clmul: %.4f s  %.0f MB/s\n", (t1-t0)/4, 60.0/((t1-t0)/4));

    /* overlap: 2 threads CTR on halves? measure pipeline:
       CTR half1 (main), then CTR half2 || GHASH half1 */
    size_t mid = blocks/2;
    unsigned char iv2[16]; memset(iv2, 0, 16); iv2[15] = 2;
    t0 = now();
    for (int k = 0; k < 4; k++) {
        aesni_ctr32_encrypt_blocks(pt, ct, mid, aes_key, iv);
        /* parallel: use worker 0 for second half CTR, main does ghash first half */
        workers[0].in = pt + mid*16;
        workers[0].out = ct + mid*16;
        workers[0].blocks = blocks-mid;
        memcpy(workers[0].ivec, iv2, 16);
        atomic_store(&workers[0].done, 0);
        atomic_store(&workers[0].go, 1);
        memset(Xi, 0, 16);
        gcm_ghash_clmul(Xi, Ht, ct, mid*16);
        while (!atomic_load(&workers[0].done)) ;
        gcm_ghash_clmul(Xi, Ht, ct+mid*16, (blocks-mid)*16);
    }
    t1 = now();
    printf("pipeline 2-way: %.4f s  %.0f MB/s\n", (t1-t0)/4, 60.0/((t1-t0)/4));

    /* 4-way pipeline: encrypt quarter, hash previous, 3 stages overlap more carefully
       Just parallel 4 CTR then ghash — upper if we had parallel ghash. */
    for (int i = 0; i < MAXTH; i++) atomic_store(&workers[i].stop, 1);
    for (int i = 0; i < MAXTH; i++) pthread_join(th[i], NULL);
    return 0;
