typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t blocks;
    const void *key;
    unsigned char ivec[16];
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int go, done, stop;
    pthread_t th;
    int started;
} ctr_worker_t;

static void *ctr_fn(void *arg) {
    ctr_worker_t *w = (ctr_worker_t *)arg;
    pthread_mutex_lock(&w->mu);
    while (!w->stop) {
        while (!w->go && !w->stop)
            pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) break;
        w->go = 0;
