static pthread_once_t g_once = PTHREAD_ONCE_INIT;

static void worker_boot(void) {
    memset(&g_worker, 0, sizeof(g_worker));
    pthread_mutex_init(&g_worker.mu, NULL);
    pthread_cond_init(&g_worker.cv, NULL);
    pthread_create(&g_worker.th, NULL, ctr_fn, &g_worker);
    g_worker.started = 1;
}

static void worker_run(const unsigned char *in, unsigned char *out, size_t blocks,
                       const void *key, const unsigned char ivec[16]) {
    pthread_once(&g_once, worker_boot);
