    pthread_mutex_unlock(&g_worker.mu);
}

static void worker_wait(void) {
    pthread_mutex_lock(&g_worker.mu);
    while (!g_worker.done)
        pthread_cond_wait(&g_worker.cv, &g_worker.mu);
    pthread_mutex_unlock(&g_worker.mu);
}

static PyObject *evp_encrypt(Py_buffer *key, Py_buffer *nonce, Py_buffer *plaintext, Py_buffer *aad, int have_aad) {
    const EVP_CIPHER *cipher = NULL;
    if (key->len == 16) cipher = EVP_aes_128_gcm();
    else if (key->len == 24) cipher = EVP_aes_192_gcm();
    else if (key->len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyErr_SetString(PyExc_ValueError, "Invalid key size");
        return NULL;
    }
    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, plaintext->len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) { Py_XDECREF(ct_obj); Py_XDECREF(tag_obj); return NULL; }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ok = 0, outlen = 0, written = 0;
    if (!ctx) goto done;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) goto done;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce->len, NULL) != 1) goto done;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key->buf, nonce->buf) != 1) goto done;
    if (have_aad && aad->len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad->buf, (int)aad->len) != 1) goto done;
    }
    if (plaintext->len > 0) {
        if (EVP_EncryptUpdate(ctx, ct, &outlen, plaintext->buf, (int)plaintext->len) != 1) goto done;
        written = outlen;
    }
    if (EVP_EncryptFinal_ex(ctx, ct + written, &outlen) != 1) goto done;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) goto done;
    ok = 1;
done:
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    if (!ok) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyErr_SetString(PyExc_RuntimeError, "AES-GCM encryption failed");
        return NULL;
    }
    return Py_BuildValue("NN", ct_obj, tag_obj);
}

static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, plaintext, aad;
    int have_aad = 1;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &plaintext, &aad)) {
        PyErr_Clear();
