    if (nonce.len != 12) {
        PyObject *r = evp_encrypt(&key, &nonce, &plaintext, &aad, have_aad);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&plaintext);
        if (have_aad) PyBuffer_Release(&aad);
