}

static void workers_wait(int i) {
    worker_t *w = &g_workers[i];
    pthread_mutex_lock(&w->mu);
    while (!w->done)
        pthread_cond_wait(&w->cv, &w->mu);
    pthread_mutex_unlock(&w->mu);
}

static PyObject *evp_encrypt(Py_buffer *key, Py_buffer *nonce, Py_buffer *plaintext,
                             Py_buffer *aad, int have_aad) {
    const EVP_CIPHER *cipher = NULL;
    if (key->len == 16) cipher = EVP_aes_128_gcm();
    else if (key->len == 24) cipher = EVP_aes_192_gcm();
    else if (key->len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyErr_SetString(PyExc_ValueError, "Invalid key size");
        return NULL;
    }
    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, plaintext->len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) { Py_XDECREF(ct_obj); Py_XDECREF(tag_obj); return NULL; }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ok = 0, outlen = 0, written = 0;
    if (!ctx) goto done;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) goto done;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce->len, NULL) != 1) goto done;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key->buf, nonce->buf) != 1) goto done;
    if (have_aad && aad->len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad->buf, (int)aad->len) != 1) goto done;
    }
    if (plaintext->len > 0) {
        if (EVP_EncryptUpdate(ctx, ct, &outlen, plaintext->buf, (int)plaintext->len) != 1) goto done;
        written = outlen;
    }
    if (EVP_EncryptFinal_ex(ctx, ct + written, &outlen) != 1) goto done;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) goto done;
    ok = 1;
done:
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    if (!ok) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyErr_SetString(PyExc_RuntimeError, "AES-GCM encryption failed");
        return NULL;
    }
    return Py_BuildValue("NN", ct_obj, tag_obj);
}

static PyObject *aesgcm_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, plaintext, aad;
    int have_aad = 1;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &plaintext, &aad)) {
        PyErr_Clear();
        have_aad = 0;
        if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &plaintext))
            return NULL;
    }
    if (key.len != 16 && key.len != 24 && key.len != 32) {
        PyErr_SetString(PyExc_ValueError, "Invalid key size");
        goto release_err;
    }
    /* Small or non-96-bit-nonce: EVP is fine and simpler. */
    if (nonce.len != 12 || plaintext.len < 256 * 1024) {
        PyObject *r = evp_encrypt(&key, &nonce, &plaintext, &aad, have_aad);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&plaintext);
        if (have_aad) PyBuffer_Release(&aad);
        return r;
    }

    pthread_once(&g_once, workers_boot);

    unsigned char aes_key[256] __attribute__((aligned(64)));
    memset(aes_key, 0, sizeof(aes_key));
    if (aesni_set_encrypt_key((unsigned char *)key.buf, (int)key.len * 8, aes_key) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "key setup failed");
        goto release_err;
    }

    unsigned char H[16], zero[16] = {0};
    aesni_encrypt(zero, H, aes_key);
    /* H in data/gmult order is the raw AES output. init wants bswap8 of that. */
    unsigned char H_init[16];
    bswap8_copy(H_init, H);

    unsigned char tables[MAX_POW][1024] __attribute__((aligned(64)));
    memset(tables, 0, sizeof(tables));
    gcm_init_clmul(tables[0], H_init);

    unsigned char power[16];
    memcpy(power, H, 16); /* data-order H^1 */
    for (int i = 1; i < MAX_POW; i++) {
        /* square: power = power * power, via table of current power */
        gcm_gmult_clmul(power, tables[i - 1]);
        unsigned char pinit[16];
        bswap8_copy(pinit, power);
        gcm_init_clmul(tables[i], pinit);
    }

    unsigned char j0[16];
    memcpy(j0, nonce.buf, 12);
    j0[12] = 0; j0[13] = 0; j0[14] = 0; j0[15] = 1;
    unsigned char ekj0[16];
    aesni_encrypt(j0, ekj0, aes_key);
    unsigned char ctr0[16];
    inc32_copy(ctr0, j0, 1);

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, plaintext.len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) {
        Py_XDECREF(ct_obj); Py_XDECREF(tag_obj);
        goto release_err;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);

    size_t pt_len = (size_t)plaintext.len;
    size_t nblocks = pt_len >> 4;
    size_t rem = pt_len & 15;
    /* Parallel path requires full blocks; remainder handled after. Workers only see full blocks.
       If rem, the parallel region is nblocks (full blocks only). */
    const unsigned char *pt = (const unsigned char *)plaintext.buf;
    size_t aad_len = (have_aad && aad.buf) ? (size_t)aad.len : 0;

    int nth = NTHREADS;
    if ((size_t)nth > nblocks) nth = (int)nblocks;
    if (nth < 1) nth = 1;
    size_t chunk = nblocks / (size_t)nth;

    for (int i = 0; i < nth; i++) {
        size_t off = (size_t)i * chunk;
        size_t nb = (i == nth - 1) ? (nblocks - off) : chunk;
        unsigned char civ[16];
        inc32_copy(civ, ctr0, (uint32_t)off);
        workers_dispatch(i, pt + off * 16, ct + off * 16, nb, aes_key, civ, tables[0]);
    }
    for (int i = 0; i < nth; i++)
        workers_wait(i);

    /* Combine chunk Xis. Chunk i covers blocks [off, off+nb) and its Xi is GHASH of that slice
       as if the slice started the message, i.e. first block * H^{nb} ... last * H^1.
       Multiply by H^{blocks_after} to place it in the full CT hash. */
    unsigned char acc[16];
    memset(acc, 0, 16);
    for (int i = 0; i < nth; i++) {
        size_t off = (size_t)i * chunk;
        size_t nb = (i == nth - 1) ? (nblocks - off) : chunk;
        size_t after = nblocks - (off + nb);
        unsigned char x[16];
        memcpy(x, g_workers[i].Xi, 16);
        if (after)
            mul_H_pow(x, tables, after);
        for (int k = 0; k < 16; k++)
            acc[k] ^= x[k];
    }

    /* Remainder block (partial). */
    if (rem) {
        unsigned char next_ctr[16], stream[16];
        inc32_copy(next_ctr, ctr0, (uint32_t)nblocks);
        aesni_encrypt(next_ctr, stream, aes_key);
        size_t base = nblocks * 16;
        for (size_t i = 0; i < rem; i++)
            ct[base + i] = pt[base + i] ^ stream[i];
        unsigned char last[16];
        memset(last, 0, 16);
        memcpy(last, ct + base, rem);
        /* This partial block is the last CT block, so it is multiplied by H^1 only.
           acc currently is GHASH of the full blocks (as a prefix). Append last:
           acc = acc * H  XOR  last * H = ghash one block of (conceptually) continuing.
           Easiest: ghash the single padded block onto acc. */
        gcm_ghash_clmul(acc, tables[0], last, 16);
    }

    /* AAD precedes CT. acc is GHASH(CT_padded). Final data hash before lengths:
       GHASH(AAD) * H^{ct_blocks_padded} XOR GHASH(CT). */
    size_t ct_blocks_padded = nblocks + (rem ? 1 : 0);
    if (aad_len) {
        unsigned char Ya[16];
        memset(Ya, 0, 16);
        size_t full = aad_len & ~(size_t)15;
        size_t r = aad_len & 15;
        if (full)
            gcm_ghash_clmul(Ya, tables[0], (unsigned char *)aad.buf, full);
        if (r) {
            unsigned char last[16];
            memset(last, 0, 16);
            memcpy(last, (unsigned char *)aad.buf + full, r);
            gcm_ghash_clmul(Ya, tables[0], last, 16);
        }
        size_t aad_blocks = (aad_len + 15) >> 4;
        /* Ya is GHASH(AAD). Multiply by H^{ct_blocks_padded}. */
        if (ct_blocks_padded)
            mul_H_pow(Ya, tables, ct_blocks_padded);
        for (int k = 0; k < 16; k++)
            acc[k] ^= Ya[k];
    }

    unsigned char lengths[16];
    uint64_t alen_bits = (uint64_t)aad_len * 8;
    uint64_t clen_bits = (uint64_t)pt_len * 8;
    for (int i = 7; i >= 0; i--) {
        lengths[i] = (unsigned char)(alen_bits & 0xff);
        alen_bits >>= 8;
        lengths[8 + i] = (unsigned char)(clen_bits & 0xff);
        clen_bits >>= 8;
    }
    gcm_ghash_clmul(acc, tables[0], lengths, 16);
    for (int i = 0; i < 16; i++)
        tag[i] = acc[i] ^ ekj0[i];

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&plaintext);
    if (have_aad) PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct_obj, tag_obj);

release_err:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&plaintext);
    if (have_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", aesgcm_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_fast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_aesgcm_fast(void) {
    return PyModule_Create(&moduledef);
}
